#include <Servo.h>
Servo s;
void setup(){ s.attach(9); }
void loop(){ s.write(0); delay(500); s.write(180); delay(500); }

#define LED 2
void setup(){ pinMode(LED,OUTPUT); }
void loop(){ digitalWrite(LED,HIGH); delay(500); digitalWrite(LED,LOW); delay(500); }

#include <WiFi.h>
void setup(){ Serial.begin(115200); WiFi.mode(WIFI_STA); WiFi.disconnect(); delay(100); Serial.println("scan..."); int n=WiFi.scanNetworks(); Serial.println(n); }
void loop(){}

#include <WiFi.h>
const char* ssid="..."; const char* pw="..."; WiFiServer s(80);
void setup(){ pinMode(2,OUTPUT); WiFi.begin(ssid,pw); while(WiFi.status()!=WL_CONNECTED) delay(500); s.begin(); }
void loop(){ WiFiClient c=s.available(); if(c){ String r=c.readStringUntil('\r'); if(r.indexOf("/on")>0) digitalWrite(2,HIGH); if(r.indexOf("/off")>0) digitalWrite(2,LOW); c.println("HTTP/1.1 200 OK"); c.stop(); } }

bool state=false; unsigned long last=0;
void setup(){ pinMode(2,INPUT_PULLUP); pinMode(13,OUTPUT);}
void loop(){ if(!digitalRead(2) && millis()-last>150){ state=!state; digitalWrite(13,state); last=millis();} }

int c=0; unsigned long last=0;
void setup(){ pinMode(2,INPUT_PULLUP); Serial.begin(9600);}
void loop(){ if(!digitalRead(2) && millis()-last>150){ c++; Serial.println(c); last=millis();} }

int mode=0;
void setup(){ pinMode(2,INPUT_PULLUP); pinMode(3,INPUT_PULLUP);}
void loop(){ if(!digitalRead(2)) mode=(mode+1)%4; if(!digitalRead(3)) mode=(mode+3)%4; delay(150); }

float dist(){ digitalWrite(9,LOW); delayMicroseconds(2); digitalWrite(9,HIGH); delayMicroseconds(10); digitalWrite(9,LOW); return pulseIn(10,HIGH)/58.0; }
void setup(){ pinMode(9,OUTPUT); pinMode(10,INPUT); pinMode(8,OUTPUT); }
void loop(){ if(dist()<20){ tone(8,1500,200);} delay(300); }

#include <Servo.h>
Servo s; float dist(){ digitalWrite(9,LOW); delayMicroseconds(2); digitalWrite(9,HIGH); delayMicroseconds(10); digitalWrite(9,LOW); return pulseIn(10,HIGH)/58.0; }
void setup(){ pinMode(9,OUTPUT); pinMode(10,INPUT); s.attach(6); Serial.begin(9600); }
void loop(){ for(int a=0;a<=180;a+=30){ s.write(a); delay(300); Serial.print(a); Serial.print(" "); Serial.println(dist()); } }

#include <Servo.h>
Servo d; float dist(){ digitalWrite(9,LOW); delayMicroseconds(2); digitalWrite(9,HIGH); delayMicroseconds(10); digitalWrite(9,LOW); return pulseIn(10,HIGH)/58.0; }
void setup(){ pinMode(9,OUTPUT); pinMode(10,INPUT); d.attach(6); }
void loop(){ if(dist()<50) d.write(90); else d.write(0); delay(200); }

float dist(){ digitalWrite(9,LOW); delayMicroseconds(2); digitalWrite(9,HIGH); delayMicroseconds(10); digitalWrite(9,LOW); return pulseIn(10,HIGH)/58.0; }
void setup(){ pinMode(9,OUTPUT); pinMode(10,INPUT); for(int i=2;i<=4;i++) pinMode(i,OUTPUT); }
void loop(){ float d=dist(); digitalWrite(2,d>50); digitalWrite(3,d>25&&d<=50); digitalWrite(4,d<=25); delay(200); }

#include <DHT.h>
#include <LiquidCrystal_I2C.h>
DHT d(2,DHT11); LiquidCrystal_I2C lcd(0x27,16,2);
void setup(){ lcd.init(); lcd.backlight(); d.begin(); } void loop(){ lcd.setCursor(0,0); lcd.print(d.readTemperature()); lcd.print("C"); lcd.setCursor(0,1); lcd.print(d.readHumidity()); lcd.print("%"); delay(2000); }

#include <DHT.h>
#include <Adafruit_SSD1306.h>
DHT d(2,DHT22); Adafruit_SSD1306 o(128,64,&Wire,-1);
void setup(){ d.begin(); o.begin(SSD1306_SWITCHCAPVCC,0x3C); } void loop(){ o.clearDisplay(); o.setCursor(0,0); o.print(d.readTemperature()); o.println("C"); o.print(d.readHumidity()); o.println("%"); o.display(); delay(2000); }

#include <Servo.h>
Servo d; float dist(){ digitalWrite(6,LOW); delayMicroseconds(2); digitalWrite(6,HIGH); delayMicroseconds(10); digitalWrite(6,LOW); return pulseIn(7,HIGH)/58.0; }
void setup(){ d.attach(9); pinMode(6,OUTPUT); pinMode(7,INPUT);} void loop(){ d.write(dist()<50?90:0); delay(200); }

#include <Adafruit_SSD1306.h>
#include <DHT.h>
Adafruit_SSD1306 o(128,64,&Wire,-1); DHT d(2,DHT22); void setup(){ o.begin(SSD1306_SWITCHCAPVCC,0x3C); d.begin(); } void loop(){ o.clearDisplay(); o.setCursor(0,0); o.print(d.readTemperature()); o.println("C"); o.print(d.readHumidity()); o.println("%"); o.display(); delay(2000); }

#include <LiquidCrystal_I2C.h>
#include <DHT.h>
LiquidCrystal_I2C lcd(0x27,16,2); DHT d(2,DHT22); void setup(){ lcd.init(); lcd.backlight(); d.begin(); } void loop(){ lcd.setCursor(0,0); lcd.print("T:"); lcd.print(d.readTemperature()); lcd.print("C"); lcd.setCursor(0,1); lcd.print("H:"); lcd.print(d.readHumidity()); lcd.print("%"); delay(2000); }

#include <OneWire.h>
#include <DallasTemperature.h>
OneWire ow(2); DallasTemperature s(&ow); void setup(){ s.begin(); Serial.begin(9600);} void loop(){ s.requestTemperatures(); Serial.println(s.getTempCByIndex(0)); delay(1000); }
